      {/* --- SHARE MODAL (CUSTOM OVERLAY) --- */}
      {showShareModal && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setShowShareModal(false)}>
